/**
 * @suppress
 */
public object FfiConverterTypeNotificationProvider: FfiConverter<NotificationProvider, Long> {
    internal val handleMap = UniffiHandleMap<NotificationProvider>()

    override fun lower(value: NotificationProvider): Long {
        if (value is NotificationProviderImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): NotificationProvider {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return NotificationProviderImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): NotificationProvider {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: NotificationProvider) = 8UL

    override fun write(value: NotificationProvider, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



